            TimeoutMs = timeoutMs;
            TaskQueue = taskQueue;
            _declared = declared;
            _inScope = inScope;
        }

        private void Declare(string step, object? input, IEnumerable<string>? after = null)
        {
            if (!_declared.Add(step)) throw new ArgumentException($"Duplicate step '{step}' in workflow '{Name}'");
            foreach (var d in after ?? Enumerable.Empty<string>())
                if (d == step || !_declared.Contains(d)) throw new ArgumentException($"Step '{step}' in workflow '{Name}' waits (after:) for unknown or later step '{d}'");
            var deps = new List<string>();
            Dsl.Dependencies(input, deps);
            foreach (var d in deps)
                if (d == step || !_declared.Contains(d)) throw new ArgumentException($"Step '{step}' references unknown or later step '{d}'");
        }

        private void CheckCondition(string step, DataRef? onlyIf)
        {
            if (onlyIf == null) return;
            var deps = new List<string>();
            Dsl.Dependencies(onlyIf, deps);
            foreach (var d in deps)
                if (d == step || !_declared.Contains(d)) throw new ArgumentException($"Step '{step}' in workflow '{Name}': onlyIf refers to unknown or later step '{d}'");
        }

        public WorkflowBlueprint Query(string name, DataRef expr)
        {
            Queries[name] = expr;
            return this;
        }

        /// <summary>The workflow's structure as data, as the worker registers it with the gateway (CONTRACT.md).</summary>
        public Dictionary<string, object?> ToBlueprint()
        {
            var blueprint = new Dictionary<string, object?>
            {
                ["name"] = Name,
                ["version"] = Version,
                ["task_queue"] = TaskQueue,
                ["queries"] = Queries.ToDictionary(kv => kv.Key, kv => (object?)kv.Value.Expr),
                ["nodes"] = BlueprintNodes(_nodes),
            };
            if (TimeoutMs is { } deadline) blueprint["timeout_ms"] = deadline; // the whole run's deadline, enforced by the engine
            if (Continuation != null) blueprint["continue_as_new"] = new Dictionary<string, object?>(Continuation);
            if (_changes.Count > 0)
                blueprint["changes"] = _changes.Select(kv => new Dictionary<string, object?> { ["id"] = kv.Key, ["min"] = kv.Value.Min, ["max"] = kv.Value.Max }).ToList();
            if (_updates.Count > 0)
                blueprint["updates"] = _updates.ToDictionary(u => u.Name, u => (object?)UpdateSpec(u));
            return blueprint;
        }

        private static Dictionary<string, object?> UpdateSpec(UpdateDef u)
        {
            var spec = new Dictionary<string, object?>();
            if (u.Handler != null) spec["handler"] = true;
            if (u.Validate != null) spec["validate"] = u.Validate.Expr;
            if (!string.IsNullOrEmpty(u.Message)) spec["message"] = u.Message;
            if (u.Input != null) spec["input"] = Dsl.Template(u.Input, $"update {u.Name}.input");
            if (u.Result != null) spec["result"] = Dsl.Template(u.Result, $"update {u.Name}.result");
            if (u.TimeoutMs is { } timeout) spec["timeout_ms"] = timeout;
            return spec;
        }

        private static List<Dictionary<string, object?>> BlueprintNodes(List<Node> nodes) => nodes.Select(n =>
        {
            var node = new Dictionary<string, object?> { ["name"] = n.Name, ["kind"] = n.Kind };
            switch (n.Kind)
            {
                case "parallel":
                case "sequence":
                    node["children"] = BlueprintNodes(n.Children ?? new List<Node>());
                    break;
                case "scope":
                    node["children"] = BlueprintNodes(n.Children ?? new List<Node>());
                    if (n.TimeoutMs is { } scopeTimeout) node["timeout_ms"] = scopeTimeout;
                    if (n.NonCancellable) node["non_cancellable"] = true;
                    break;
                case "wait_for":
                    node["signal"] = n.Signal;
                    node["timeout_ms"] = n.Ms;
                    break;
                case "timer":
                    node["for_ms"] = n.Ms;
                    break;
                case "child":
                    node["workflow"] = n.Workflow;
                    if (n.Input != null) node["input"] = Dsl.Template(n.Input, $"{n.Name}.input");
                    break;
                default:
                    node["activity"] = Dsl.HandlerName(n.Handler);
                    node["references"] = n.Input == null ? new List<string> { "${input}" } : Dsl.References(n.Input);
                    if (n.TimeoutMs is { } timeout) node["timeout_ms"] = timeout;
                    if (n.HeartbeatMs is { } beat) node["heartbeat_ms"] = beat;
                    if (n.ScheduleToStartMs is { } toStart) node["schedule_to_start_ms"] = toStart;
                    if (n.Retry is { } r) node["retry"] = RetryJson(r);
                    break;
            }
            if (n.Kind is "step" or "wait_for" or "timer" or "child")
            {
                if (n.Compensate is { } c)
                    node["compensate"] = new Dictionary<string, object?>
                    {
                        ["activity"] = Dsl.HandlerName(c.Handler),
                        ["references"] = Dsl.References(c.Input ?? Dsl.Output(n.Name)),
                    };
                if (n.OnlyIf is { } cond) node["only_if"] = cond.Expr;
                if (n.Gate is { } gate)
                {
                    var g = new Dictionary<string, object?> { ["change"] = gate.Change };
                    if (gate.Min is { } min) g["min"] = min;
                    if (gate.Max is { } max) g["max"] = max;
                    node["gate"] = g;
                }
            }
            if (n.After is { Count: > 0 } after) node["after"] = after.ToList();
            return node;
        }).ToList();

        private static Dictionary<string, object?> RetryJson(RetryPolicy r)
        {
            var retry = new Dictionary<string, object?> { ["attempts"] = r.Attempts, ["initial_ms"] = r.InitialMs, ["backoff"] = r.Backoff, ["maximum_ms"] = r.MaximumMs };
            if (r.NonRetryable is { Count: > 0 } types) retry["non_retryable"] = types.ToList();
            return retry;
        }

        /// <summary>
        /// A step. <c>after</c> names earlier steps it also waits for (on top of what precedes it, e.g. a sibling in a
        /// <c>Parallel</c> group); <c>timeoutMs</c> limits one attempt, <c>heartbeatMs</c> (at least 1000) how long the
        /// handler may go without calling <c>ctx.HeartbeatAsync()</c>, <c>scheduleToStartMs</c> (at least 1000) how long the
        /// step may wait for a worker; <c>onlyIf</c> (a reference) runs the step only when it is truthy (not null, false or
        /// ""), else the step is skipped; <c>gate</c> (see <see cref="Dsl.Gate"/>) runs it only on one side of a change. The
        /// engine enforces them; each is sent only when set.
        /// </summary>
        public WorkflowBlueprint Step(string name, TaskHandler handler, object? input = null, RetryPolicy? retry = null, Compensation? compensate = null,
                                      IEnumerable<string>? after = null, long? timeoutMs = null, long? heartbeatMs = null, long? scheduleToStartMs = null,
                                      DataRef? onlyIf = null, Gate? gate = null)
        {
            var deps = after?.ToList();
            CheckCondition(name, onlyIf);
            Declare(name, input, deps);
            _nodes.Add(new Node("step", name, handler, input, retry, compensate, After: deps, TimeoutMs: timeoutMs, HeartbeatMs: heartbeatMs, ScheduleToStartMs: scheduleToStartMs,
                                OnlyIf: onlyIf, Gate: gate));
            return this;
        }

        /// <summary>
        /// A durable wait for a signal; its output is the signal's payload. <c>after</c> names earlier steps it also waits
        /// for; <c>onlyIf</c> (a reference) waits only when it is truthy, else the node is skipped; <c>compensate</c> undoes
        /// the wait (its input defaults to the signal's payload) when the run fails; <c>gate</c> waits only on one side of a
        /// change. The engine enforces them.
        /// </summary>
        public WorkflowBlueprint WaitFor(string name, string signal, long timeoutMs = 600000, IEnumerable<string>? after = null,
                                         DataRef? onlyIf = null, Compensation? compensate = null, Gate? gate = null)
        {
            var deps = after?.ToList();
            CheckCondition(name, onlyIf);
            Declare(name, null, deps);
            _nodes.Add(new Node("wait_for", name, Compensate: compensate, Signal: signal, Ms: timeoutMs, After: deps, OnlyIf: onlyIf, Gate: gate));
            return this;
        }

        /// <summary>
        /// A durable wait for a time. <c>after</c> names earlier steps it also waits for; <c>onlyIf</c> (a reference) waits
        /// only when it is truthy, else the node is skipped; <c>compensate</c> undoes the timer (its input defaults to the
        /// timer's output) when the run fails; <c>gate</c> waits only on one side of a change. The engine enforces them.
        /// </summary>
        public WorkflowBlueprint Timer(string name, long forMs, IEnumerable<string>? after = null, DataRef? onlyIf = null, Compensation? compensate = null,
                                       Gate? gate = null)
        {
            var deps = after?.ToList();
            CheckCondition(name, onlyIf);
            Declare(name, null, deps);
            _nodes.Add(new Node("timer", name, Compensate: compensate, Ms: forMs, After: deps, OnlyIf: onlyIf, Gate: gate));
            return this;
        }

        /// <summary>
        /// Runs another workflow (a blueprint) as a step; its output is the child run's output, its failure the node's.
        /// See <see cref="Child(string, string, object?, Compensation?, IEnumerable{string}?, DataRef?, Gate?)"/>.
        /// </summary>
        public WorkflowBlueprint Child(string name, WorkflowBlueprint workflow, object? input = null,
                                       Compensation? compensate = null, IEnumerable<string>? after = null, DataRef? onlyIf = null,
                                       Gate? gate = null)
            => Child(name, workflow.Name, input, compensate, after, onlyIf, gate);

        /// <summary>
        /// Runs another workflow (any registered one, by name) as a step; its output is the child run's output, its failure
        /// the node's. The engine starts the child and resolves <c>input</c> (references only: <c>Input()</c>,
        /// <c>Output()</c>, <c>Ref()</c>, in objects and lists; the run's input when null; a literal value is an
        /// <see cref="ArgumentException"/> here). <c>compensate</c> undoes it (its input defaults to the child's output),
        /// <c>onlyIf</c> runs it only when truthy, <c>gate</c> only on one side of a change. A child is not retried: give the child workflow's own steps retries, and
        /// the child workflow a <c>timeout_ms</c>. The child workflow must be registered before a run reaches this step.
        /// </summary>
        public WorkflowBlueprint Child(string name, string workflow, object? input = null,
                                       Compensation? compensate = null, IEnumerable<string>? after = null, DataRef? onlyIf = null,
                                       Gate? gate = null)
        {
            if (input != null) Dsl.Template(input, $"{name}.input");
            var deps = after?.ToList();
            CheckCondition(name, onlyIf);
            Declare(name, input, deps);
            _nodes.Add(new Node("child", name, Input: input, Compensate: compensate, After: deps, OnlyIf: onlyIf, Workflow: workflow, Gate: gate));
            return this;
        }

        /// <summary>
        /// When the run ends (and <c>onlyIf</c>, a reference, is truthy), it closes <c>continued_as_new</c> and a fresh run of
        /// this workflow starts with <c>input</c> (references only, resolved by the engine; the same input when null), at
        /// most <c>maxRuns</c> runs; <c>maxEvents</c> also continues it once its history has grown past that many events (at a
        /// point the engine picks). Each is sent only when set.
        /// </summary>
        public WorkflowBlueprint ContinueAsNew(object? input = null, DataRef? onlyIf = null, int? maxRuns = null, int? maxEvents = null)
        {
            var policy = new Dictionary<string, object?>();
            if (input != null) policy["input"] = Dsl.Template(input, "continue_as_new.input");
            if (onlyIf != null) policy["only_if"] = onlyIf.Expr;
            if (maxRuns is { } runs) policy["max_runs"] = runs;
            if (maxEvents is { } events) policy["max_events"] = events;
            Continuation = policy;
            return this;
        }

        /// <summary>
        /// Declares a change (versioning, like Temporal's getVersion): runs that reach a gated node fresh take
        /// <paramref name="max"/>, runs that went past it on the old path keep 0; nodes pick a side with
        /// <c>gate: Dsl.Gate(id, min, max)</c>. Raise <paramref name="min"/> only once no open run is on an older path.
        /// <paramref name="min"/> above <paramref name="max"/> is an <see cref="ArgumentException"/>.
        /// </summary>
        public WorkflowBlueprint Change(string id, int min = 0, int max = 1)
        {
            if (min > max) throw new ArgumentException($"change '{id}' in workflow '{Name}': min is above max");
            _changes[id] = (min, max);
            return this;
        }

        /// <summary>
        /// An update handler (<see cref="JoobQClient.UpdateWorkflowAsync"/>): <paramref name="validate"/> (a reference, e.g.
        /// <c>Dsl.UpdateInput("name")</c>) must be truthy or the update is rejected with <paramref name="message"/>; then
        /// <paramref name="handler"/> runs as a step of the run (activity <c>&lt;workflow&gt;/@update/&lt;name&gt;</c>; its
        /// payload is <paramref name="input"/>, by default the update's input, resolved by the engine; it is not retried;
        /// <paramref name="timeoutMs"/> defaults to 30 s) and its return value is the result, or, without one,
        /// <paramref name="result"/> is the result. <paramref name="input"/> and <paramref name="result"/> are templates of
        /// references (<c>Input()</c>, <c>Output()</c>, <c>UpdateInput()</c>, <c>Ref()</c>; a literal is an
        /// <see cref="ArgumentException"/>), as is a second update of the same name. Each is sent only when set.
        /// </summary>
        public WorkflowBlueprint Update(string name, TaskHandler? handler = null, DataRef? validate = null, string? message = null,
                                        object? input = null, object? result = null, long? timeoutMs = null)
        {
            if (_updates.Any(u => u.Name == name)) throw new ArgumentException($"Duplicate update '{name}' in workflow '{Name}'");
            if (input != null) Dsl.Template(input, $"update {name}.input");
            if (result != null) Dsl.Template(result, $"update {name}.result");
            _updates.Add(new UpdateDef(name, handler, validate, message, input, result, timeoutMs));
            return this;
        }

        /// <summary>
        /// A cancellation scope: the nodes built on the given blueprint run in sequence and can be cancelled as a unit (from
        /// the console or API, or after <paramref name="timeoutMs"/> from its first step's start) while the rest of the run
        /// goes on; a cancelled step counts as finished with a null output, and a running one sees the cancel through
        /// <c>ctx.HeartbeatAsync()</c> (true: stop early). A <paramref name="nonCancellable"/> scope holds cleanup that still
        /// runs when the workflow is cancelled, times out or fails (it cannot have a timeout). Scopes do not nest; an empty
        /// scope, a nested one or a non-cancellable one with a timeout is an <see cref="ArgumentException"/>.
        /// </summary>
        public WorkflowBlueprint Scope(string name, Action<WorkflowBlueprint> build, long? timeoutMs = null, bool nonCancellable = false)
        {
            if (_inScope) throw new ArgumentException($"scope '{name}' in workflow '{Name}' is inside another scope: scopes do not nest");
            if (nonCancellable && timeoutMs != null) throw new ArgumentException($"scope '{name}' is non_cancellable and cannot time out");
            var sub = new WorkflowBlueprint(Name, Version, TimeoutMs, TaskQueue, _declared, true);
            build(sub);
            if (sub._nodes.Count == 0) throw new ArgumentException($"scope '{name}' in workflow '{Name}' has no steps");
            _nodes.Add(new Node("scope", name, Children: sub._nodes, TimeoutMs: timeoutMs, NonCancellable: nonCancellable));
            return this;
        }

        /// <summary>Starts the branches built on the given blueprint together; what follows waits for every branch.</summary>
        public WorkflowBlueprint Parallel(Action<WorkflowBlueprint> build) => Group("parallel", build);

        /// <summary>Runs the nodes built on the given blueprint in order.</summary>
        public WorkflowBlueprint Sequence(Action<WorkflowBlueprint> build) => Group("sequence", build);

        private WorkflowBlueprint Group(string kind, Action<WorkflowBlueprint> build)
        {
            var sub = new WorkflowBlueprint(Name, Version, TimeoutMs, TaskQueue, _declared, _inScope);
            build(sub);
            _nodes.Add(new Node(kind, $"{kind}_{_nodes.Count + 1}", Children: sub._nodes));
            return this;
        }

        /// <summary>
        /// The handlers of this workflow's steps (and of the compensations of its steps, waits, timers and children, and its
        /// update handlers), by the activity name the engine sends them under (<c>&lt;workflow&gt;/&lt;step&gt;</c>, compensations
        /// <c>&lt;workflow&gt;/&lt;step&gt;/compensate</c>, updates <c>&lt;workflow&gt;/@update/&lt;name&gt;</c>). Each runs its step once:
        /// the engine conducts the run (it retries, compensates and waits). A step's input is resolved against the run's
        /// input (the task's payload) and the outputs of the steps that completed (the task's checkpoints).
        /// </summary>
        public Dictionary<string, TaskHandler> Activities()
        {
            var found = new Dictionary<string, TaskHandler>();
            void Visit(List<Node> nodes)
            {
                foreach (var node in nodes)
                {
                    switch (node.Kind)
                    {
                        case "sequence":
                        case "parallel":
                        case "scope":
                            Visit(node.Children ?? new List<Node>());
                            break;
                        default:
                            var step = node;
                            if (step.Kind == "step")
                                found[ActivityName(Name, step.Name)] = (input, ctx) => step.Handler!(Dsl.Resolve(step.Input, input, Done(ctx)), ctx);
                            if (step.Compensate is { } comp) // a step, wait, timer or child can be undone
                                found[ActivityName(Name, step.Name, true)] =
                                    (input, ctx) => comp.Handler(Dsl.Resolve(comp.Input ?? Dsl.Output(step.Name), input, Done(ctx)), ctx);
                            break;
                    }
                }
            }
            Visit(_nodes);
            foreach (var update in _updates)
            {
                if (update.Handler is { } handler) // the engine resolved the handler's input already: the payload is passed as is
                    found[UpdateActivityName(Name, update.Name)] = (payload, ctx) => handler(payload, ctx);
            }
            return found;
        }

        /// <summary>The activity the engine sends a step (or its compensation) of an SDK workflow under.</summary>
        public static string ActivityName(string workflowName, string step, bool compensate = false)
            => compensate ? $"{workflowName}/{step}/compensate" : $"{workflowName}/{step}";

        /// <summary>The activity the engine sends an update handler of an SDK workflow under (<c>&lt;workflow&gt;/@update/&lt;name&gt;</c>).</summary>
        public static string UpdateActivityName(string workflowName, string update) => $"{workflowName}/@update/{update}";

        private static readonly IReadOnlyDictionary<string, JsonNode?> NoSteps = new Dictionary<string, JsonNode?>();

        /// <summary>The outputs of the run's completed steps, as the step's task carries them.</summary>
        private static IReadOnlyDictionary<string, JsonNode?> Done(ExecutionContext ctx) => ctx.Task.Checkpoints ?? NoSteps;
    }

    /// <summary>A task as the gateway leases it.</summary>
    public sealed class LeasedTask
    {
        [JsonPropertyName("lease_token")] public string LeaseToken { get; set; } = "";
        [JsonPropertyName("kind")] public string Kind { get; set; } = "";
        [JsonPropertyName("id")] public string Id { get; set; } = "";
        [JsonPropertyName("queue")] public string Queue { get; set; } = "";
        [JsonPropertyName("name")] public string Name { get; set; } = "";
        [JsonPropertyName("attempt")] public int Attempt { get; set; }
        [JsonPropertyName("max_retries")] public int MaxRetries { get; set; }
        [JsonPropertyName("payload")] public JsonNode? Payload { get; set; }
        [JsonPropertyName("context")] public Dictionary<string, JsonNode?>? Context { get; set; }
        [JsonPropertyName("workflow_id")] public string? WorkflowId { get; set; }
        [JsonPropertyName("step_id")] public string? StepId { get; set; }
        /// <summary>A workflow step's: the outputs of the run's completed steps (its references resolve against them).</summary>
        [JsonPropertyName("checkpoints")] public Dictionary<string, JsonNode?>? Checkpoints { get; set; }
        [JsonPropertyName("lease_until_ms")] public long LeaseUntilMs { get; set; }
        /// <summary>An engine step's heartbeat timeout (null for most tasks): call <c>ctx.HeartbeatAsync()</c> more often than this.</summary>
        [JsonPropertyName("heartbeat_ms")] public long? HeartbeatMs { get; set; }
    }

    /// <summary>What a running worker's transport offers a handler: cancellation, without HTTP.</summary>
    public interface ITaskTransport
    {
        bool CancelRequested(string leaseToken);
    }

    /// <summary>What a handler gets besides its input: the request context, the task, heartbeats.</summary>
    public sealed class ExecutionContext
    {
        private readonly JoobQClient? _client;
        private readonly long _leaseTtlMs;
        private readonly ITaskTransport? _transport;
        private readonly object _beatLock = new();
        private long _lastBeatTicks = long.MinValue;
        private bool _beatCancel;

        public LeasedTask Task { get; }
        public string WorkerId { get; }
        /// <summary>The request context the producer attached (tenant_id, request_id, traceparent, ...).</summary>
        public Dictionary<string, JsonNode?> Context { get; }
        public int Attempt => Task.Attempt;

        public ExecutionContext(LeasedTask task, string workerId, JoobQClient? client, long leaseTtlMs = 30000, ITaskTransport? transport = null)
        {
            _transport = transport;
            Task = task;
            WorkerId = workerId;
            Context = new Dictionary<string, JsonNode?>(task.Context ?? new());
            _client = client;
            _leaseTtlMs = leaseTtlMs;
        }

        public string DedupeKey => $"{Task.WorkflowId ?? Task.Id}:{Task.StepId ?? Task.Name}:{Task.Attempt}";

        /// <summary>
        /// True when cancellation was requested. In a running worker it answers what the last lease renewal said (and asks
        /// for one) without waiting for the gateway; the worker renews every lease on its own. For a step with
        /// <c>heartbeat_ms</c> it also tells the engine the step is alive (<c>POST /sdk/tasks/:token/heartbeat</c>, at most
        /// every third of <c>heartbeat_ms</c>): the worker's own renewals do not, so a handler that stops calling this is timed out.
        /// </summary>
        public async Task<bool> HeartbeatAsync(CancellationToken ct = default)
        {
            if (Task.HeartbeatMs is { } beatMs && beatMs > 0 && _client != null)
            {
                var due = false;
                var now = Stopwatch.GetTimestamp(); // monotonic
                var interval = Math.Max(100, beatMs / 3) * Stopwatch.Frequency / 1000;
                lock (_beatLock)
                {
                    if (_lastBeatTicks == long.MinValue || now - _lastBeatTicks >= interval)
                    {
                        _lastBeatTicks = now;
                        due = true;
                    }
                }
                if (due)
                {
                    try
                    {
                        var cancel = await _client.HeartbeatTaskAsync(Task.LeaseToken, WorkerId, _leaseTtlMs, ct);
                        lock (_beatLock) _beatCancel = cancel;
                    }
                    catch (Exception) when (!ct.IsCancellationRequested)
                    {
                        // the next window's beat tries again; the engine's deadline decides
                    }
                }
                bool cancelled;
                lock (_beatLock) cancelled = _beatCancel;
                if (cancelled) return true;
            }
            if (_transport != null) return _transport.CancelRequested(Task.LeaseToken);
            return _client != null && await _client.HeartbeatTaskAsync(Task.LeaseToken, WorkerId, _leaseTtlMs, ct);
        }

        private Dictionary<string, object?> Merged(Dictionary<string, object?>? extra)
        {
            var m = Context.ToDictionary(kv => kv.Key, kv => (object?)kv.Value?.DeepClone());
            if (extra != null) foreach (var (k, v) in extra) m[k] = v;
            return m;
        }

        private JoobQClient Client => _client ?? throw new InvalidOperationException("no gateway client");

        /// <summary>Enqueues a defined job (its queue, retries and sealed fields), carrying this handler's context on.</summary>
        public Task<string> EnqueueAsync(JobDefinition job, object? payload, EnqueueOptions? options = null, CancellationToken ct = default)
            => Client.EnqueueAsync(job, payload, (options ?? new EnqueueOptions()) with { Context = Merged(options?.Context) }, ct);

        public Task<string> EnqueueJobAsync(string queue, string jobType, object? payload, int maxRetries = 3, CancellationToken ct = default)
            => Client.EnqueueJobAsync(queue, jobType, payload, Merged(null), maxRetries, ct);

        /// <summary>Starts a workflow, carrying this handler's context on (see <see cref="JoobQClient.StartWorkflowAsync"/>).</summary>
        public Task<string> StartWorkflowAsync(string name, object? input = null, CancellationToken ct = default,
            string? workflowId = null, Dictionary<string, object?>? searchAttributes = null, string? build = null)
            => Client.StartWorkflowAsync(name, input, Merged(null), ct, workflowId, searchAttributes, build);

        public Task<JsonNode?> RegisterScheduleAsync(string name, string queue, string jobType, string? cron = null, string? every = null,
            string timezone = "UTC", object? payload = null, int maxRetries = 3, string[]? encryptFields = null, string? uniqueKey = null, CancellationToken ct = default)
            => Client.RegisterScheduleAsync(name, queue, jobType, cron, every, timezone, payload, maxRetries, encryptFields, uniqueKey, ct);

        public Task<RateLimitResult> RateLimitAsync(string key, int limit, long periodMs, CancellationToken ct = default)
            => Client.RateLimitAsync(key, limit, periodMs, ct);

        /// <summary>Creates a Pro batch (see <see cref="JoobQClient.CreateBatchAsync"/>); the members and callbacks carry this
        /// handler's context.</summary>
        public Task<BatchCreated> CreateBatchAsync(IEnumerable<BatchJob> jobs, BatchJob? onComplete = null, BatchJob? onSuccess = null,
            BatchJob? onFailure = null, string? description = null, CancellationToken ct = default)
            => Client.CreateBatchAsync(jobs, onComplete, onSuccess, onFailure, description, Merged(null), ct);

        /// <summary>A Pro batch's progress (see <see cref="JoobQClient.GetBatchAsync"/>).</summary>
        public Task<BatchStatus> GetBatchAsync(string batchId, CancellationToken ct = default)
            => Client.GetBatchAsync(batchId, ct);

        /// <summary>One run (Pro; 402 without a licence). See <see cref="JoobQClient.DescribeWorkflowAsync"/>.</summary>
        public Task<JsonNode?> DescribeWorkflowAsync(string workflowId, CancellationToken ct = default)
            => Client.DescribeWorkflowAsync(workflowId, ct);

        /// <summary>The run at the end of the workflow's chain, waiting up to <paramref name="waitMs"/> for it to close (Pro).</summary>
        public Task<JsonNode?> WorkflowResultAsync(string workflowId, long waitMs = 0, CancellationToken ct = default)
            => Client.WorkflowResultAsync(workflowId, waitMs, ct);

        /// <summary>The run's events after <paramref name="afterSeq"/>, oldest first (Pro).</summary>
        public Task<JsonArray> WorkflowHistoryAsync(string workflowId, long afterSeq = 0, int limit = 200, CancellationToken ct = default)
            => Client.WorkflowHistoryAsync(workflowId, afterSeq, limit, ct);

        /// <summary>Asks the run a read-only question (Pro); returns the answer.</summary>
        public Task<JsonNode?> QueryWorkflowAsync(string workflowId, string name, CancellationToken ct = default)
            => Client.QueryWorkflowAsync(workflowId, name, ct);

        /// <summary>Sends a signal to a workflow run; true when the gateway accepted it.</summary>
        public Task<bool> SignalWorkflowAsync(string workflowId, string name, object? payload = null, CancellationToken ct = default)
            => Client.SignalWorkflowAsync(workflowId, name, payload, ct);

        /// <summary>Sets and/or removes search attributes of the workflow's open run (Pro); returns <c>{id, attributes}</c>.</summary>
        public Task<JsonNode?> UpsertWorkflowAttributesAsync(string workflowId, Dictionary<string, object?>? set = null, IEnumerable<string>? remove = null, CancellationToken ct = default)
            => Client.UpsertWorkflowAttributesAsync(workflowId, set, remove, ct);

        /// <summary>Sends an update to a running workflow's update handler (Pro). See <see cref="JoobQClient.UpdateWorkflowAsync"/>.</summary>
        public Task<JsonNode?> UpdateWorkflowAsync(string workflowId, string name, object? input = null, string? updateId = null, long? waitMs = null, CancellationToken ct = default)
            => Client.UpdateWorkflowAsync(workflowId, name, input, updateId, waitMs, ct);
    }

    /// <summary>The gateway's HTTP client (<c>/api/v1/sdk/*</c>, bearer <c>JOOBQUI_SDK_TOKEN</c>).</summary>
    public sealed class JoobQClient
    {
        private static readonly JsonSerializerOptions JsonOptions = new() { DefaultIgnoreCondition = JsonIgnoreCondition.Never };
        private readonly HttpClient _http;
        private readonly string _gatewayUrl;
        private readonly string _token;
        private readonly Func<Dictionary<string, object?>>? _contextProvider;
        public string? ServiceName { get; set; } = Environment.GetEnvironmentVariable("JOOBQ_SERVICE_NAME");
        public string? Team { get; set; } = Environment.GetEnvironmentVariable("JOOBQ_TEAM");

        /// <summary>
        /// How long one gateway call may take. A worker lowers it: a call that hangs for longer than a lease would let
        /// every lease the worker holds expire while its tasks still run.
        /// </summary>
        public TimeSpan RequestTimeout { get; set; } = TimeSpan.FromSeconds(60);

        public JoobQClient(string gatewayUrl, string token, HttpClient? http = null, Func<Dictionary<string, object?>>? contextProvider = null)
        {
            _gatewayUrl = gatewayUrl.TrimEnd('/');
            _token = token;
            _http = http ?? new HttpClient { Timeout = TimeSpan.FromSeconds(60) };
            _contextProvider = contextProvider;
        }

        private Dictionary<string, object?> ContextOf(Dictionary<string, object?>? explicitContext)
        {
            var m = _contextProvider?.Invoke() ?? new Dictionary<string, object?>();
            if (explicitContext != null) foreach (var (k, v) in explicitContext) m[k] = v;
            return m;
        }

        /// <summary>Enqueues a defined job now (or after its delay) with its queue, retries and sealed fields.</summary>
        public async Task<string> EnqueueAsync(JobDefinition job, object? payload, EnqueueOptions? options = null, CancellationToken ct = default)
        {
            var res = await PostAsync("/api/v1/sdk/jobs", JobBody(job, payload, options), ct);
            return res?["jid"]?.GetValue<string>() ?? "";
        }

        private Dictionary<string, object?> JobBody(JobDefinition job, object? payload, EnqueueOptions? options)
        {
            var o = options ?? new EnqueueOptions();
            return new Dictionary<string, object?>
            {
                ["queue"] = job.Queue, ["job_type"] = job.Name, ["payload"] = payload ?? new Dictionary<string, object?>(),
                ["context"] = ContextOf(o.Context), ["jid"] = o.Jid, ["max_retries"] = job.Retries, ["delay_ms"] = o.DelayMs, ["run_at_ms"] = o.RunAtMs, ["expires_ms"] = o.ExpiresMs, ["timeout_ms"] = o.TimeoutMs,
                ["encrypt_fields"] = job.EncryptedFields, ["unique_key"] = o.UniqueKey, ["unique_mode"] = o.UniqueMode, ["unique_ttl_ms"] = job.UniqueTtlMs,
            };
        }

        /// <summary>
        /// Enqueues many jobs of one definition with <c>POST /sdk/jobs/batch</c> (500 per call); answers one
        /// <c>{jid, queue, status}</c> per job, in order.
        /// </summary>
        public async Task<List<JsonNode?>> EnqueueManyAsync(JobDefinition job, IEnumerable<(object? Payload, EnqueueOptions? Options)> jobs, CancellationToken ct = default)
        {
            var bodies = jobs.Select(j => (object?)JobBody(job, j.Payload, j.Options)).ToList();
            var output = new List<JsonNode?>();
            for (var start = 0; start < bodies.Count; start += 500)
            {
                var res = await PostAsync("/api/v1/sdk/jobs/batch", new Dictionary<string, object?> { ["jobs"] = bodies.Skip(start).Take(500).ToList() }, ct);
                if (res?["jobs"] is JsonArray arr) output.AddRange(arr.Select(n => n?.DeepClone()));
            }
            return output;
        }

        public async Task<string> EnqueueJobAsync(string queue, string jobType, object? payload, Dictionary<string, object?>? context = null, int maxRetries = 3, CancellationToken ct = default)
        {
            var res = await PostAsync("/api/v1/sdk/jobs", new Dictionary<string, object?>
            {
                ["queue"] = queue, ["job_type"] = jobType, ["payload"] = payload ?? new Dictionary<string, object?>(),
                ["context"] = ContextOf(context), ["max_retries"] = maxRetries,
            }, ct);
            return res?["jid"]?.GetValue<string>() ?? "";
        }

        /// <summary>
        /// Starts a workflow run and answers its id. <paramref name="workflowId"/> picks the id (the gateway makes one
        /// when null), <paramref name="searchAttributes"/> sets the run's search attributes and <paramref name="build"/>
        /// pins it to a worker build (both Pro). The engine runs it on the task queue of the blueprint registered as
        /// <paramref name="name"/>.
        /// </summary>
        public async Task<string> StartWorkflowAsync(string name, object? input = null, Dictionary<string, object?>? context = null, CancellationToken ct = default,
            string? workflowId = null, Dictionary<string, object?>? searchAttributes = null, string? build = null)
        {
            var res = await PostAsync("/api/v1/sdk/workflows", new Dictionary<string, object?>
            {
                ["name"] = name, ["input"] = input, ["context"] = ContextOf(context),
                ["id"] = workflowId, ["search_attributes"] = searchAttributes, ["build"] = build,
            }, ct);
            return res?["id"]?.GetValue<string>() ?? "";
        }

        /// <summary>
        /// Creates a Pro batch with <c>POST /sdk/batches</c>: 1 to 1000 member jobs (without a unique key) and callback jobs.
        /// <paramref name="onFailure"/> is enqueued at the first dead member, <paramref name="onComplete"/> once every member
        /// completed or was dead-lettered, <paramref name="onSuccess"/> then too when none was dead; each once, with
        /// <c>{"batch": {id, kind, total, succeeded, failed}}</c> merged into its payload. 402 pro_required without a Pro
        /// licence.
        /// </summary>
        public async Task<BatchCreated> CreateBatchAsync(IEnumerable<BatchJob> jobs, BatchJob? onComplete = null, BatchJob? onSuccess = null,
            BatchJob? onFailure = null, string? description = null, Dictionary<string, object?>? context = null, CancellationToken ct = default)
        {
            var body = new Dictionary<string, object?>
            {
                ["description"] = description,
                ["jobs"] = jobs.Select(j => (object?)BatchJobBody(j, context)).ToList(),
            };
            if (onComplete != null) body["on_complete"] = BatchJobBody(onComplete, context);
            if (onSuccess != null) body["on_success"] = BatchJobBody(onSuccess, context);
            if (onFailure != null) body["on_failure"] = BatchJobBody(onFailure, context);
            var res = await PostAsync("/api/v1/sdk/batches", body, ct);
            var answers = res?["jobs"] is JsonArray arr ? arr.Select(n => n?.DeepClone()).ToList() : new List<JsonNode?>();
            return new BatchCreated(res?["batch_id"]?.GetValue<string>() ?? "", (int)(res?["total"]?.GetValue<double>() ?? 0), answers);
        }

        /// <summary>A Pro batch's progress with <c>GET /sdk/batches/:id</c>.</summary>
        public async Task<BatchStatus> GetBatchAsync(string batchId, CancellationToken ct = default)
        {
            var res = await GetAsync($"/api/v1/sdk/batches/{Uri.EscapeDataString(batchId)}", ct);
            long Num(string key) => (long)(res?[key]?.GetValue<double>() ?? 0);
            return new BatchStatus(res?["batch_id"]?.GetValue<string>() ?? "", res?["description"]?.GetValue<string>(),
                res?["status"]?.GetValue<string>() ?? "", (int)Num("total"), (int)Num("pending"), (int)Num("succeeded"),
                (int)Num("failed"), Num("created_at"), res?["finished_at"] is JsonNode f ? (long)f.GetValue<double>() : null);
        }

        private Dictionary<string, object?> BatchJobBody(BatchJob j, Dictionary<string, object?>? context)
        {
            var o = j.Options ?? new EnqueueOptions();
            var ctx = context == null ? new Dictionary<string, object?>() : new Dictionary<string, object?>(context);
            if (o.Context != null) foreach (var (k, v) in o.Context) ctx[k] = v;
            return new Dictionary<string, object?>
            {
                ["queue"] = j.Queue, ["job_type"] = j.JobType, ["payload"] = j.Payload ?? new Dictionary<string, object?>(),
                ["context"] = ContextOf(ctx), ["jid"] = o.Jid, ["max_retries"] = j.MaxRetries, ["delay_ms"] = o.DelayMs, ["run_at_ms"] = o.RunAtMs,
                ["expires_ms"] = o.ExpiresMs, ["timeout_ms"] = o.TimeoutMs, ["encrypt_fields"] = j.EncryptFields ?? Array.Empty<string>(),
                ["unique_key"] = o.UniqueKey, ["unique_mode"] = o.UniqueMode, ["unique_ttl_ms"] = j.UniqueTtlMs,
            };
        }

        /// <summary>Asks the gateway's Pro rate limiter whether <paramref name="key"/> may proceed (<c>limit</c> hits per <c>periodMs</c>).</summary>
        public async Task<RateLimitResult> RateLimitAsync(string key, int limit, long periodMs, CancellationToken ct = default)
        {
            var res = await PostAsync("/api/v1/sdk/rate-limit", new Dictionary<string, object?> { ["key"] = key, ["limit"] = limit, ["period_ms"] = periodMs }, ct);
            return new RateLimitResult(res?["allowed"]?.GetValue<bool>() ?? false, (long)(res?["retry_after_ms"]?.GetValue<double>() ?? 0));
        }

        /// <summary>Registers a job schedule (pass exactly one of <paramref name="cron"/> or <paramref name="every"/>, e.g. "3 seconds"); the gateway keeps it by name.</summary>
        public Task<JsonNode?> RegisterScheduleAsync(string name, string queue, string jobType, string? cron = null, string? every = null,
            string timezone = "UTC", object? payload = null, int maxRetries = 3, string[]? encryptFields = null, string? uniqueKey = null, CancellationToken ct = default)
            => PostAsync("/api/v1/sdk/schedules", new Dictionary<string, object?>
            {
                ["name"] = name, ["kind"] = "job", ["cron"] = cron, ["every"] = every, ["timezone"] = timezone,
                ["queue"] = queue, ["job_type"] = jobType, ["payload"] = payload ?? new Dictionary<string, object?>(),
                ["max_retries"] = maxRetries, ["encrypt_fields"] = encryptFields ?? Array.Empty<string>(), ["unique_key"] = uniqueKey,
            }, ct);

        public async Task<bool> SignalWorkflowAsync(string id, string name, object? payload = null, CancellationToken ct = default)
        {
            var res = await PostAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(id)}/signal", new Dictionary<string, object?> { ["name"] = name, ["payload"] = payload }, ct);
            return res?["accepted"]?.GetValue<bool>() ?? false;
        }

        /// <summary>
        /// Sends an update to a running workflow's update handler (Pro; 402 without a licence) and waits up to
        /// <paramref name="waitMs"/> (100 to 30000, default 10000) for its outcome: <c>{update_id, name, status, result,
        /// error, reason, message}</c>. <c>status</c> is <c>completed</c>, <c>rejected</c> (validate failed: <c>reason</c>,
        /// <c>message</c>), <c>failed</c>, or <c>accepted</c> when the handler had not answered in time (the gateway's 202,
        /// not an error: send again with the same <paramref name="updateId"/> to wait for the same update).
        /// </summary>
        public Task<JsonNode?> UpdateWorkflowAsync(string workflowId, string name, object? input = null, string? updateId = null, long? waitMs = null, CancellationToken ct = default)
        {
            var body = new Dictionary<string, object?> { ["name"] = name, ["input"] = input };
            if (updateId != null) body["update_id"] = updateId;
            if (waitMs is { } wait) body["wait_ms"] = wait;
            return PostAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(workflowId)}/updates", body, ct);
        }

        /// <summary>
        /// One run (Pro; 402 without a licence): <c>{id, name, status, closed, run, started_at, closed_at, continued_to,
        /// output, failure, attributes, queries}</c>. Payload fields with secret-looking names are masked, as in the console.
        /// </summary>
        public Task<JsonNode?> DescribeWorkflowAsync(string workflowId, CancellationToken ct = default)
            => GetAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(workflowId)}", ct);

        /// <summary>
        /// The run at the end of the workflow's continue-as-new chain (Pro; 402 without a licence), waiting up to
        /// <paramref name="waitMs"/> (at most 25000) for it to close; same shape as <see cref="DescribeWorkflowAsync"/>.
        /// <c>closed</c> false means it was still open when the wait ended.
        /// </summary>
        public Task<JsonNode?> WorkflowResultAsync(string workflowId, long waitMs = 0, CancellationToken ct = default)
            => GetAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(workflowId)}/result?wait_ms={waitMs}", ct);

        /// <summary>The run's events after <paramref name="afterSeq"/> (Pro; 402 without a licence), at most <paramref name="limit"/>, oldest first.</summary>
        public async Task<JsonArray> WorkflowHistoryAsync(string workflowId, long afterSeq = 0, int limit = 200, CancellationToken ct = default)
        {
            var res = await GetAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(workflowId)}/history?after_seq={afterSeq}&limit={limit}", ct);
            return res?["items"]?.DeepClone() as JsonArray ?? new JsonArray();
        }

        /// <summary>Asks the run a read-only question (Pro; 402 without a licence); returns the answer (any JSON).</summary>
        public async Task<JsonNode?> QueryWorkflowAsync(string workflowId, string name, CancellationToken ct = default)
        {
            var res = await PostAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(workflowId)}/query", new Dictionary<string, object?> { ["name"] = name }, ct);
            return res?["result"]?.DeepClone();
        }

        /// <summary>Sets and/or removes search attributes of the workflow's open run (Pro; 402 without a licence); returns <c>{id, attributes}</c>.</summary>
        public Task<JsonNode?> UpsertWorkflowAttributesAsync(string workflowId, Dictionary<string, object?>? set = null, IEnumerable<string>? remove = null, CancellationToken ct = default)
            => PostAsync($"/api/v1/sdk/workflows/{Uri.EscapeDataString(workflowId)}/search-attributes",
                new Dictionary<string, object?> { ["set"] = set, ["remove"] = remove?.ToArray() }, ct);

        /// <summary>Sends a workflow's blueprint; the gateway keeps each new content hash (<c>created</c>) and ignores a known one.</summary>
        public Task<JsonNode?> RegisterBlueprintAsync(WorkflowBlueprint workflow, string? workerId = null, CancellationToken ct = default)
            => PostAsync("/api/v1/sdk/blueprints", new Dictionary<string, object?>
            {
                ["name"] = workflow.Name, ["sdk_language"] = "dotnet", ["worker_id"] = workerId, ["blueprint"] = workflow.ToBlueprint(),
            }, ct);

        public Task RegisterWorkerAsync(string workerId, IEnumerable<string> taskQueues, int concurrency = 4, CancellationToken ct = default)
            => PostAsync("/api/v1/sdk/workers/register", new Dictionary<string, object?>
            {
                ["worker_id"] = workerId, ["sdk_language"] = "dotnet", ["sdk_version"] = JoobQSdkInfo.Version,
                ["service_name"] = ServiceName, ["team"] = Team, ["host"] = Environment.MachineName, ["pid"] = Environment.ProcessId,
                ["task_queues"] = taskQueues.ToArray(), ["concurrency"] = concurrency, ["delivery_mode"] = "poll",
            }, ct);

        public Task DeregisterWorkerAsync(string workerId, CancellationToken ct = default)
            => PostAsync($"/api/v1/sdk/workers/{Uri.EscapeDataString(workerId)}/deregister", new Dictionary<string, object?>(), ct);

        public async Task<List<LeasedTask>> PollTasksAsync(string workerId, IEnumerable<string> taskQueues, int maxTasks = 1, long timeoutMs = 0, long leaseTtlMs = 30000, CancellationToken ct = default)
        {
            var res = await PostAsync("/api/v1/sdk/tasks/poll", new Dictionary<string, object?>
            {
                ["worker_id"] = workerId, ["task_queues"] = taskQueues.ToArray(), ["max_tasks"] = maxTasks,
                ["timeout_ms"] = timeoutMs, ["lease_ttl_ms"] = leaseTtlMs,
            }, ct);
            return res?["tasks"]?.Deserialize<List<LeasedTask>>() ?? new List<LeasedTask>();
        }

        public async Task<bool> HeartbeatTaskAsync(string leaseToken, string workerId, long leaseTtlMs = 30000, CancellationToken ct = default)
        {
            var res = await PostAsync($"/api/v1/sdk/tasks/{Uri.EscapeDataString(leaseToken)}/heartbeat", new Dictionary<string, object?>
            {
                ["worker_id"] = workerId, ["lease_ttl_ms"] = leaseTtlMs,
            }, ct);
            return res?["cancel_requested"]?.GetValue<bool>() ?? false;
        }

        public Task CompleteTaskAsync(string leaseToken, string workerId, object? output = null, CancellationToken ct = default)
            => PostAsync($"/api/v1/sdk/tasks/{Uri.EscapeDataString(leaseToken)}/complete", new Dictionary<string, object?>
            {
                ["worker_id"] = workerId, ["output"] = output,
            }, ct);

        public Task FailTaskAsync(string leaseToken, string workerId, Exception ex, bool retryable = true, CancellationToken ct = default)
        {
            var body = Failure(ex, retryable);
            body["worker_id"] = workerId;
            return PostAsync($"/api/v1/sdk/tasks/{Uri.EscapeDataString(leaseToken)}/fail", body, ct);
        }

        /// <summary>
        /// Settles up to 100 leases in one call (<c>POST /sdk/tasks/ack</c>). An item is <c>{token, outcome: "complete",
        /// output}</c> or <c>{token, outcome: "fail", ...Failure(ex)}</c>; each gets its own result.
        /// </summary>
        public async Task<JsonArray> AckTasksAsync(string workerId, IReadOnlyList<Dictionary<string, object?>> items, CancellationToken ct = default)
        {
            var res = await PostAsync("/api/v1/sdk/tasks/ack", new Dictionary<string, object?> { ["worker_id"] = workerId, ["items"] = items }, ct);
            return res?["results"] as JsonArray ?? new JsonArray();
        }

        /// <summary>Renews many leases in one call (<c>POST /sdk/tasks/heartbeat</c>); leases are <c>{token}</c>.</summary>
        public async Task<JsonArray> HeartbeatTasksAsync(string workerId, IReadOnlyList<Dictionary<string, object?>> leases, long leaseTtlMs = 30000, CancellationToken ct = default)
        {
            var res = await PostAsync("/api/v1/sdk/tasks/heartbeat", new Dictionary<string, object?>
            {
                ["worker_id"] = workerId, ["lease_ttl_ms"] = leaseTtlMs, ["leases"] = leases,
            }, ct);
            return res?["leases"] as JsonArray ?? new JsonArray();
        }

        /// <summary>The fields that report <paramref name="ex"/> to the gateway (fail, and a fail item of <c>AckTasksAsync</c>).</summary>
        public static Dictionary<string, object?> Failure(Exception ex, bool retryable = true)
        {
            var frames = new StackTrace(ex, true).GetFrames()
                .Select(f => new Dictionary<string, object?>
                {
                    ["file"] = f.GetFileName() ?? f.GetMethod()?.DeclaringType?.FullName ?? "unknown",
                    ["line"] = Math.Max(0, f.GetFileLineNumber()),
                    ["function"] = $"{f.GetMethod()?.DeclaringType?.FullName}.{f.GetMethod()?.Name}",
                }).ToList();
            var message = string.IsNullOrWhiteSpace(ex.Message) ? ex.GetType().FullName ?? "Exception" : ex.Message;
            var raw = ex.ToString();
            return new Dictionary<string, object?>
            {
                ["error_class"] = ex.GetType().Name, ["error_message"] = message.Length > 4000 ? message[..4000] : message,
                ["retryable"] = retryable, ["sdk_language"] = "dotnet", ["stack_frames"] = frames,
                ["raw_stacktrace"] = raw.Length > 4000 ? raw[..4000] : raw,
            };
        }

        private Task<JsonNode?> PostAsync(string path, object body, CancellationToken ct) => SendAsync(HttpMethod.Post, path, body, ct);

        private Task<JsonNode?> GetAsync(string path, CancellationToken ct) => SendAsync(HttpMethod.Get, path, null, ct);

        private async Task<JsonNode?> SendAsync(HttpMethod method, string path, object? body, CancellationToken ct)
        {
            using var req = new HttpRequestMessage(method, _gatewayUrl + path);
            if (body != null) req.Content = new StringContent(JsonSerializer.Serialize(body, JsonOptions), Encoding.UTF8, "application/json");
            req.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _token);
            // Set on the request, so an X-JoobQ-SDK among the HttpClient's DefaultRequestHeaders is not sent.
            req.Headers.TryAddWithoutValidation("X-JoobQ-SDK", "dotnet/" + JoobQSdkInfo.Version);
            using var limit = CancellationTokenSource.CreateLinkedTokenSource(ct);
            limit.CancelAfter(RequestTimeout);
            using var res = await _http.SendAsync(req, limit.Token);
            var text = await res.Content.ReadAsStringAsync(limit.Token);
            if ((int)res.StatusCode >= 300) throw GatewayException.Of((int)res.StatusCode, text);
            return string.IsNullOrWhiteSpace(text) ? null : JsonNode.Parse(text);
        }
    }

    /// <summary>
    /// In-app worker: runs up to <c>Concurrency</c> jobs and workflow steps at once inside the booted application,
    /// and on SIGTERM/SIGINT (or cancellation, or <c>Stop</c>) drains, sends the outcomes and deregisters.
    /// Its gateway calls run as tasks of their own, never in a handler's way: a poll loop keeps a small buffer of leased
    /// tasks (free slots plus <c>Prefetch</c>), an ack loop sends the outcomes handlers queue (<c>POST /sdk/tasks/ack</c>,
    /// up to 100 per call after at most <c>AckLinger</c>, retried while the gateway is unavailable; a task stays leased
    /// until its outcome is acknowledged; when <c>AckBuffer</c> outcomes wait, handlers wait), and a heartbeat loop
    /// renews every lease the worker holds in one call (<c>POST /sdk/tasks/heartbeat</c>).
    /// </summary>
    public sealed class JoobQWorker
    {
        private readonly JoobQClient _client;
        private readonly string _workerId;
        private readonly List<string> _queues;
        private readonly Dictionary<string, TaskHandler> _handlers = new();
        private readonly Dictionary<string, WorkflowBlueprint> _workflows = new();
        private readonly List<Middleware> _middlewares = new();
        private readonly HashSet<string> _blueprintsSent = new();
        private readonly CancellationTokenSource _stop = new();
        // Cancels the poll in flight once the gateway refuses this SDK's version (426): the worker stops at once.
        private readonly CancellationTokenSource _abort = new();
        private SdkTooOldException? _refused;
        private Transport? _transport;
        public int Concurrency { get; set; } = 4;
        public long LeaseTtlMs { get; set; } = 30000;
        public long PollTimeoutMs { get; set; } = 5000;
        public TimeSpan DrainTimeout { get; set; } = TimeSpan.FromSeconds(30);
        /// <summary>Leases held beyond the free slots (default Concurrency / 2, at least 1).</summary>
        public int? Prefetch { get; set; }
        /// <summary>Outcomes queued for the ack loop before handlers wait (default 4 x Concurrency).</summary>
        public int? AckBuffer { get; set; }
        /// <summary>How long the ack loop waits for more outcomes before it sends a batch (default 5 ms).</summary>
        public TimeSpan AckLinger { get; set; } = TimeSpan.FromMilliseconds(5);

        public JoobQWorker(JoobQClient client, string workerId, IEnumerable<string> taskQueues)
        {
            _client = client;
            _workerId = workerId;
            _queues = taskQueues.ToList();
        }

        private void AddQueue(string q)
        {
            if (!string.IsNullOrEmpty(q) && !_queues.Contains(q)) _queues.Add(q);
        }

        public JoobQWorker Register(JobDefinition job)
        {
            AddQueue(job.Queue);
            _handlers[job.Name] = job.Perform;
            return this;
        }

        public JoobQWorker Register(WorkflowBlueprint wf)
        {
            AddQueue(wf.TaskQueue);
            _workflows[wf.Name] = wf;
            // The engine conducts the workflow's runs and sends each step as its own task.
            foreach (var (name, handler) in wf.Activities()) _handlers[name] = handler;
            return this;
        }

        /// <summary>
        /// Registers each workflow's blueprint once (first: a worker that shows up has its blueprints in; one the gateway
        /// refuses, 4xx, is logged and not sent again), then the worker.
        /// </summary>
        private async Task RegisterAsync(int concurrency)
        {
            foreach (var (name, wf) in _workflows)
            {
                lock (_blueprintsSent) { if (_blueprintsSent.Contains(name)) continue; }
                try
                {
                    await _client.RegisterBlueprintAsync(wf, _workerId);
                }
                catch (GatewayException e) when (e.Status < 500 && e is not SdkTooOldException)
                {
                    Console.Error.WriteLine($"joobq: blueprint of {name} refused: {e.Message} [JQ-902] https://joobq.io/errors/JQ-902");
                }
                lock (_blueprintsSent) { _blueprintsSent.Add(name); }
            }
            await _client.RegisterWorkerAsync(_workerId, _queues, concurrency);
        }

        public JoobQWorker Handle(string name, TaskHandler handler)
        {
            _handlers[name] = handler;
            return this;
        }

        /// <summary>
        /// Adds a middleware around every task's handler and returns the worker, so calls chain. The first one added is
        /// the outermost; the handler is the innermost call. Add them before <c>RunAsync</c>.
        /// </summary>
        public JoobQWorker Use(Middleware middleware)
        {
            ArgumentNullException.ThrowIfNull(middleware);
            _middlewares.Add(middleware);
            return this;
        }

        /// <summary>Runs the middlewares from the first added (outermost) to the handler (innermost).</summary>
        private Task<object?> InvokeAsync(TaskHandler handler, LeasedTask task, ExecutionContext ctx)
        {
            Func<Task<object?>> next = () => handler(task.Payload, ctx);
            for (var i = _middlewares.Count - 1; i >= 0; i--)
            {
                var mw = _middlewares[i];
                var inner = next;
                next = () => mw(ctx, inner);
            }
            return next();
        }

        /// <summary>Stops polling; <c>RunAsync</c> returns after the running tasks finish and their outcomes are acknowledged.</summary>
        public void Stop()
        {
            _stop.Cancel();
            _transport?.Changed.Set();
        }

        /// <summary>The gateway refused this SDK's version: stop now, without a drain (<c>RunAsync</c> throws <paramref name="e"/>).</summary>
        private void Refuse(SdkTooOldException e)
        {
            Interlocked.CompareExchange(ref _refused, e, null);
            _stop.Cancel();
            _abort.Cancel();
            _transport?.Changed.Set();
        }

        public async Task ProcessTaskAsync(LeasedTask task)
        {
            if (!_handlers.TryGetValue(task.Name, out var handler))
            {
                await SettleAsync(task, FailItem(new NonRetryableException($"No handler registered for {task.Name} [JQ-901] https://joobq.io/errors/JQ-901"), false));
                return;
            }
            var ctx = new ExecutionContext(task, _workerId, _client, LeaseTtlMs, _transport);
            object? output;
            try
            {
                output = await InvokeAsync(handler, task, ctx);
            }
            catch (Exception e)
            {
                await SettleAsync(task, FailItem(e, e is not NonRetryableException));
                return;
            }
            await SettleAsync(task, new Dictionary<string, object?>
            {
                ["outcome"] = "complete", ["output"] = output,
            });
        }

        private static Dictionary<string, object?> FailItem(Exception e, bool retryable)
        {
            var item = JoobQClient.Failure(e, retryable);
            item["outcome"] = "fail";
            return item;
        }

        /// <summary>Hands the outcome to the ack loop (waiting while its queue is full); outside <c>RunAsync</c> it is sent here.</summary>
        private async Task SettleAsync(LeasedTask task, Dictionary<string, object?> item)
        {
            item["token"] = task.LeaseToken;
            var t = _transport;
            if (t != null)
            {
                await t.SettleAsync(item);
                return;
            }
            await ReportAsync(() => _client.AckTasksAsync(_workerId, new[] { item }));
        }

        /// <summary>
        /// Sends an outcome, retrying while the gateway is unavailable; a lost outcome is left to the lease. An
        /// <see cref="SdkTooOldException"/> is thrown, not retried.
        /// </summary>
        private static async Task ReportAsync(Func<Task> call)
        {
            var delay = 250;
            for (var i = 0; i < 6; i++)
            {
                try
                {
                    await call();
                    return;
                }
                catch (SdkTooOldException)
                {
                    throw;
                }
                catch (GatewayException e) when (e.Status < 500)
                {
                    return;
                }
                catch (Exception)
                {
                    await Task.Delay(delay);
                    delay = Math.Min(delay * 2, 5000);
                }
            }
        }

        /// <summary>Something to wait for with a time limit; <c>Set</c> wakes the current waiters.</summary>
        private sealed class Signal
        {
            private TaskCompletionSource _tcs = new(TaskCreationOptions.RunContinuationsAsynchronously);
            private int _pending; // a Set nobody waited for yet: the next wait returns at once

            public async Task WaitAsync(TimeSpan timeout)
            {
                if (Interlocked.Exchange(ref _pending, 0) == 1) return;
                var current = Volatile.Read(ref _tcs);
                if (Interlocked.Exchange(ref _pending, 0) == 1) return;
                await Task.WhenAny(current.Task, Task.Delay(timeout < TimeSpan.Zero ? TimeSpan.Zero : timeout));
                Interlocked.Exchange(ref _pending, 0);
            }

            public void Set()
            {
                Volatile.Write(ref _pending, 1);
                Interlocked.Exchange(ref _tcs, new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously)).TrySetResult();
            }
        }

        /// <summary>Every lease the worker holds (buffered, running, or waiting for its ack) and the queues between its loops.</summary>
        private sealed class Transport : ITaskTransport
        {
            public readonly Channel<LeasedTask> Ready = Channel.CreateUnbounded<LeasedTask>();
            public readonly Channel<Dictionary<string, object?>> Acks;
            public readonly ConcurrentDictionary<string, bool> Leased = new();
            public readonly ConcurrentDictionary<string, bool> Cancelled = new();
            public readonly Signal Changed = new();
            public readonly Signal BeatWake = new();
            public readonly CancellationTokenSource GiveUp = new();
            public int Held; // buffered + running
            public volatile bool BeatStop;

            public Transport(int ackBuffer)
            {
                Acks = Channel.CreateBounded<Dictionary<string, object?>>(new BoundedChannelOptions(ackBuffer) { FullMode = BoundedChannelFullMode.Wait });
            }

            public async Task SettleAsync(Dictionary<string, object?> item)
            {
                try { await Acks.Writer.WriteAsync(item, GiveUp.Token); }
                catch (OperationCanceledException) { } // left to its lease
                catch (ChannelClosedException) { }
            }

            public bool CancelRequested(string token) => Cancelled.TryGetValue(token, out var c) && c;

            public void Release(string token)
            {
                Leased.TryRemove(token, out _);
                Cancelled.TryRemove(token, out _);
            }
        }

        private async Task AckLoopAsync(Transport t)
        {
            var reader = t.Acks.Reader;
            while (Volatile.Read(ref _refused) == null && await reader.WaitToReadAsync())
            {
                var batch = new List<Dictionary<string, object?>>();
                while (batch.Count < 100 && reader.TryRead(out var item)) batch.Add(item);
                if (batch.Count < 100 && AckLinger > TimeSpan.Zero)
                {
                    await Task.Delay(AckLinger);
                    while (batch.Count < 100 && reader.TryRead(out var item)) batch.Add(item);
                }
                if (batch.Count > 0 && Volatile.Read(ref _refused) == null) await SendAcksAsync(t, batch);
            }
        }

        private async Task SendAcksAsync(Transport t, List<Dictionary<string, object?>> batch)
        {
            var delay = 250;
            while (true)
            {
                try
                {
                    await _client.AckTasksAsync(_workerId, batch);
                    break; // a refused item (its lease is gone) is not sent again either
                }
                catch (SdkTooOldException e)
                {
                    Refuse(e); // never retried: the outcomes are left to their leases
                    break;
                }
                catch (GatewayException e) when (e.Status == 413 && batch.Count > 1)
                {
                    // too large for one call: in halves
                    var half = batch.Count / 2;
                    await SendAcksAsync(t, batch.GetRange(0, half));
                    await SendAcksAsync(t, batch.GetRange(half, batch.Count - half));
                    return;
                }
                catch (GatewayException e) when (e.Status < 500 && e.Status != 429)
                {
                    Console.Error.WriteLine($"joobq: the gateway refused {batch.Count} outcomes: {e.Message}");
                    break;
                }
                catch (Exception)
                {
                    // retried
                }
                if (t.GiveUp.IsCancellationRequested) break; // shutting down: the leases bring these tasks back
                await Pause(delay, t.GiveUp.Token);
                delay = Math.Min(delay * 2, 5000);
            }
            foreach (var item in batch) t.Release((string)item["token"]!);
        }

        private async Task HeartbeatLoopAsync(Transport t, int concurrency)
        {
            var every = TimeSpan.FromMilliseconds(Math.Max(500, LeaseTtlMs / 3));
            var nextAll = DateTime.UtcNow + every;
            var lastRegister = Stopwatch.StartNew();
            while (!t.BeatStop)
            {
                await t.BeatWake.WaitAsync(nextAll - DateTime.UtcNow);
                if (t.BeatStop) return;
                if (DateTime.UtcNow < nextAll) continue;
                foreach (var chunk in t.Leased.Keys.ToList().Chunk(500))
                {
                    var leases = chunk.Select(token => new Dictionary<string, object?> { ["token"] = token }).ToList();
                    try
                    {
                        foreach (var lease in await _client.HeartbeatTasksAsync(_workerId, leases, LeaseTtlMs))
                        {
                            var token = lease?["lease_token"]?.GetValue<string>() ?? "";
                            if (lease?["error"] != null) t.Leased.TryRemove(token, out _); // gone: its outcome will be refused
                            else if (t.Leased.ContainsKey(token)) t.Cancelled[token] = lease?["cancel_requested"]?.GetValue<bool>() ?? false;
                        }
                    }
                    catch (SdkTooOldException e)
                    {
                        Refuse(e);
                        return;
                    }
                    catch (Exception)
                    {
                        // renewed with the next heartbeat
                    }
                }
                nextAll = DateTime.UtcNow + every;
                if (!_stop.IsCancellationRequested && lastRegister.Elapsed > TimeSpan.FromSeconds(10))
                {
                    try { await RegisterAsync(concurrency); }
                    catch (SdkTooOldException e) { Refuse(e); return; }
                    catch (Exception) { }
                    lastRegister.Restart();
                }
            }
        }

        /// <summary>
        /// Runs until SIGTERM/SIGINT, the token, or <c>Stop</c>; then drains the running tasks, sends their outcomes and
        /// deregisters. Throws an <see cref="SdkTooOldException"/> at once when the gateway refuses this SDK's version
        /// (426 on any of its calls): it logs the server's message, stops polling and its loops, and neither drains nor
        /// deregisters (the gateway would refuse those calls too; the leases expire and the tasks are queued again). A
        /// handler already running is not cancelled; its outcome is not sent.
        /// </summary>
        public async Task RunAsync(CancellationToken cancellationToken = default)
        {
            using var linked = cancellationToken.Register(Stop);
            // One hung call must not outlast the leases: a poll waits PollTimeoutMs at the gateway, and a sixth of a
            // lease on top keeps a renewal that hangs well inside the lease (10 s with the defaults).
            var bound = TimeSpan.FromMilliseconds(PollTimeoutMs + LeaseTtlMs / 6);
            if (bound > TimeSpan.Zero && _client.RequestTimeout > bound) _client.RequestTimeout = bound;
            using var term = PosixSignalRegistration.Create(PosixSignal.SIGTERM, c => { c.Cancel = true; Stop(); });
            using var intr = PosixSignalRegistration.Create(PosixSignal.SIGINT, c => { c.Cancel = true; Stop(); });
            var stop = _stop.Token;
            var concurrency = Math.Max(1, Concurrency);
            var capacity = concurrency + Math.Max(0, Prefetch ?? Math.Max(1, concurrency / 2));
            var backoff = 250;
            while (!stop.IsCancellationRequested)
            {
                try
                {
                    await RegisterAsync(concurrency);
                    break;
                }
                catch (SdkTooOldException e)
                {
                    Console.Error.WriteLine(e.LogLine());
                    throw;
                }
                catch (Exception)
                {
                    await Pause(backoff, stop);
                    backoff = Math.Min(backoff * 2, 5000);
                }
            }
            var t = new Transport(Math.Max(1, AckBuffer ?? 4 * concurrency));
            _transport = t;
            var handlers = Enumerable.Range(0, concurrency).Select(_ => Task.Run(async () =>
            {
                await foreach (var task in t.Ready.Reader.ReadAllAsync())
                {
                    if (Volatile.Read(ref _refused) != null) break; // buffered tasks are left to their leases
                    try { await ProcessTaskAsync(task); }
                    catch (Exception e) { Console.Error.WriteLine($"joobq: task {task.Id} could not be settled: {e.Message}"); }
                    finally
                    {
                        Interlocked.Decrement(ref t.Held);
                        t.Changed.Set();
                    }
                }
            })).ToArray();
            var acker = Task.Run(() => AckLoopAsync(t));
            var beat = Task.Run(() => HeartbeatLoopAsync(t, concurrency));

            backoff = 250;
            while (!stop.IsCancellationRequested)
            {
                var room = capacity - Volatile.Read(ref t.Held);
                if (room <= 0)
                {
                    await t.Changed.WaitAsync(TimeSpan.FromMilliseconds(500));
                    continue;
                }
                List<LeasedTask> tasks;
                try
                {
                    tasks = await _client.PollTasksAsync(_workerId, _queues, Math.Min(room, 100), PollTimeoutMs, LeaseTtlMs, _abort.Token);
                    backoff = 250;
                }
                catch (SdkTooOldException e)
                {
                    Refuse(e);
                    break;
                }
                catch (Exception)
                {
                    await Pause(backoff + Random.Shared.Next(100), stop);
                    backoff = Math.Min(backoff * 2, 5000);
                    continue;
                }
                foreach (var task in tasks) t.Leased[task.LeaseToken] = true;
                Interlocked.Add(ref t.Held, tasks.Count);
                foreach (var task in tasks) t.Ready.Writer.TryWrite(task);
            }

            var deadline = DateTime.UtcNow + DrainTimeout;
            while (Volatile.Read(ref t.Held) > 0 && Volatile.Read(ref _refused) == null && DateTime.UtcNow < deadline)
                await t.Changed.WaitAsync(TimeSpan.FromMilliseconds(50));
            ThrowIfRefused(t);
            t.Ready.Writer.TryComplete();
            t.Acks.Writer.TryComplete();
            var left = deadline - DateTime.UtcNow;
            if (await Task.WhenAny(acker, Task.Delay(left < TimeSpan.Zero ? TimeSpan.Zero : left)) != acker)
            {
                t.GiveUp.Cancel();
                await Task.WhenAny(acker, Task.Delay(5000));
            }
            t.GiveUp.Cancel();
            t.BeatStop = true;
            t.BeatWake.Set();
            await Task.WhenAny(beat, Task.Delay(5000));
            ThrowIfRefused(t); // refused while the last outcomes were sent
            _transport = null;
            try { await _client.DeregisterWorkerAsync(_workerId); } catch (Exception) { }
        }

        /// <summary>
        /// Once the gateway refused this SDK's version: ends the loops without a drain or a deregistration (it refuses
        /// every call from this SDK), logs the server's message and throws the <see cref="SdkTooOldException"/>.
        /// </summary>
        private void ThrowIfRefused(Transport t)
        {
            if (Volatile.Read(ref _refused) is not { } refused) return;
            t.GiveUp.Cancel(); // a handler waiting on a full outcome queue lets go
            t.Ready.Writer.TryComplete();
            t.Acks.Writer.TryComplete();
            t.BeatStop = true;
            t.BeatWake.Set();
            Console.Error.WriteLine(refused.LogLine());
            ExceptionDispatchInfo.Capture(refused).Throw();
        }

        private static async Task Pause(int ms, CancellationToken stop)
        {
            try { await Task.Delay(ms, stop); } catch (OperationCanceledException) { }
        }
    }

}